// The Idle Adventure's Town Map (README: Idle Adventure, Town Map; the user's): FireRed's Kanto map, its places the run's
// towns, routes and dungeons, generated by tools/idle/town_map.py (data/gen1/town-map.ts). A town is travelled to
// (TRAVEL); a route or dungeon takes a Wild or Trainer grind (GRIND_AT); only those the run has reached.
import { AREAS, areaIndex, areaOpen, isTown, mapView } from './areas.js';
import { KANTO_TOWN_MAP_PLACES } from './data/gen1/town-map.js';

/**
 * The map's picture (public/idle/gen1/town-map/kanto.png: FireRed's screen cut to the map, 208x144 from (16, 16)) and its
 * grid, as region_map.c has it: 22x15 cells of 8px, from (32, 32) on the screen, (16, 16) in the picture.
 */
export const TOWN_MAP_GRID = { image: '/idle/gen1/town-map/kanto.png', imageWidth: 208, imageHeight: 144, x: 16, y: 16, cell: 8, width: 22, height: 15 } as const;

export interface TownMapPlace {
  /** Its map section (MAPSEC_, lower case). */
  section: string;
  /** Its name as the game's map shows it. */
  name: string;
  /** The run's areas there (AREAS' ids): a town's every visit (Viridian City's two), a route's or dungeon's one. */
  areas: string[];
  /** Its cells on the grid, on the map's layer or the dungeons' (a dungeon's cell over a route's: the dungeon's first). */
  cells: [x: number, y: number, layer: 'map' | 'dungeon'][];
}

export const TOWN_MAP_PLACES: readonly TownMapPlace[] = KANTO_TOWN_MAP_PLACES;

/** The place at a grid cell, the dungeons' layer first, or null. */
export function townMapPlaceAt(x: number, y: number): TownMapPlace | null {
  const at = (layer: 'map' | 'dungeon') => TOWN_MAP_PLACES.find((p) => p.cells.some(([cx, cy, l]) => cx === x && cy === y && l === layer));
  return at('dungeon') ?? at('map') ?? null;
}

/**
 * The area a place stands for in a run that has reached `reached` (AREAS' index): a town's latest visit reached (Viridian
 * City with its gym once there), a route's or dungeon's own (one off the main road once its `opens` is reached; a
 * main-road route's first, Route 21's before its tall grass: townMapAreas has both); null when none is reached yet.
 */
export function townMapArea(place: TownMapPlace, reached: number): number | null {
  const indices = townMapAreas(place, reached);
  if (!indices.length) return null;
  return isTown(AREAS[indices[0]!]!) ? indices[indices.length - 1]! : indices[0]!;
}

/** Every area of a place a run that has reached `reached` can go to (a route's grinds are offered in each: Route 21's and its tall grass's). */
export function townMapAreas(place: TownMapPlace, reached: number): number[] {
  return place.areas.map(areaIndex).filter((i) => i >= 0 && areaOpen(i, reached));
}

/**
 * The place an area is on (a gym or a League room: its town's; grinding from a town: the town's); with the map the run
 * is on, the place of that map's section among the area's (Route 17 of Routes 16, 17 and 18).
 */
export function townMapPlaceOf(index: number, map?: string): TownMapPlace | null {
  let a = AREAS[index];
  if (!a) return null;
  if (a.kind === 'gym' && a.town) a = AREAS[areaIndex(a.town)]!;
  if (a.kind === 'league') a = AREAS.find((t) => isTown(t) && t.id === 'indigo-plateau') ?? a;
  const id = a.id;
  const section = map && mapView(map).section;
  return (section && TOWN_MAP_PLACES.find((p) => p.areas.includes(id) && p.section === section)) || (TOWN_MAP_PLACES.find((p) => p.areas.includes(id)) ?? null);
}
